pub inline fn propertyHelper(self: *SizeHandler, comptime property: []const u8, comptime T: type, value: *const T, comptime category: PropertyCategory, dest: *css.DeclarationList, context: *css.PropertyHandlerContext) void {
            if (((@field(PropertyCategory, @tagName(category)) != self.category) or (((@field(self, property) != null) and (context.targets.browsers != null)) and (!value.isCompatible(context.targets.browsers.?))))) {
                _ = self.flush(dest, context);
            }
            @field(self, property) = value.deepClone(context.allocator);
            self.category = category;
            self.has_any = true;
    }

pub fn flush(self: *SizeHandler, dest: *css.DeclarationList, context: *css.PropertyHandlerContext) void {
            if ((!self.has_any)) {
                return;
            }
            self.has_any = false;
            const logical_supported = (!context.shouldCompileLogical(Feature.logical_size));
            _ = self.flushPropertyHelper(PropertyIdTag.width, "width", Size, dest, context);
            _ = self.flushPropertyHelper(PropertyIdTag.@"min-width", "min_width", Size, dest, context);
            _ = self.flushPropertyHelper(PropertyIdTag.@"max-width", "max_width", MaxSize, dest, context);
            _ = self.flushPropertyHelper(PropertyIdTag.height, "height", Size, dest, context);
            _ = self.flushPropertyHelper(PropertyIdTag.@"min-height", "min_height", Size, dest, context);
            _ = self.flushPropertyHelper(PropertyIdTag.@"max-height", "max_height", MaxSize, dest, context);
            _ = self.flushLogicalHelper(PropertyIdTag.@"block-size", "block_size", PropertyIdTag.height, Size, logical_supported, dest, context);
            _ = self.flushLogicalHelper(PropertyIdTag.@"min-block-size", "min_block_size", PropertyIdTag.@"min-height", Size, logical_supported, dest, context);
            _ = self.flushLogicalHelper(PropertyIdTag.@"max-block-size", "max_block_size", PropertyIdTag.@"max-height", MaxSize, logical_supported, dest, context);
            _ = self.flushLogicalHelper(PropertyIdTag.@"inline-size", "inline_size", PropertyIdTag.width, Size, logical_supported, dest, context);
            _ = self.flushLogicalHelper(PropertyIdTag.@"min-inline-size", "min_inline_size", PropertyIdTag.@"min-width", Size, logical_supported, dest, context);
            _ = self.flushLogicalHelper(PropertyIdTag.@"max-inline-size", "max_inline_size", PropertyIdTag.@"max-width", MaxSize, logical_supported, dest, context);
    }

pub fn finalize(self: *SizeHandler, dest: *css.DeclarationList, context: *css.PropertyHandlerContext) void {
            _ = self.flush(dest, context);
            self.flushed_properties = SizeProperty{  };
    }

pub inline fn flushPrefixHelper(self: *SizeHandler, comptime property: PropertyIdTag, comptime SizeType: type, comptime feature: css.prefixes.Feature, dest: *css.DeclarationList, context: *css.PropertyHandlerContext) void {
            if ((!@field(self.flushed_properties, @tagName(property)))) {
                const prefixes = context.targets.prefixes(css.VendorPrefix{ .none = true }, feature).difference(css.VendorPrefix{ .none = true });
                inline for (css.VendorPrefix.FIELDS) |field| {
                    if (@field(prefixes, field)) {
                        var prefix: css.VendorPrefix = .{};
                        _ = &prefix;
                        @field(prefix, field) = true;
                        _ = (blk_catch_2: { break :blk_catch_2 ((dest.append(context.allocator, @unionInit(Property, @tagName(property), @unionInit(SizeType, @tagName(feature), prefix)))) catch |e| { _ = &e; break :blk_catch_2 bun.handleOom(e); }); });
                    }
                }
            }
    }

pub inline fn flushPropertyHelper(self: *SizeHandler, comptime property: PropertyIdTag, comptime field: []const u8, comptime SizeType: type, dest: *css.DeclarationList, context: *css.PropertyHandlerContext) void {
            if (bun.take((&@field(self, field)))) |val| {
                _ = &val;
                switch (val) {
.stretch => |vp| {
_ = (if ((vp == css.VendorPrefix{ .none = true })) blk: {
                break :blk self.flushPrefixHelper(property, SizeType, .stretch, dest, context);

} else null);
},
.min_content => |vp| {
_ = (if ((vp == css.VendorPrefix{ .none = true })) blk: {
                break :blk self.flushPrefixHelper(property, SizeType, .min_content, dest, context);

} else null);
},
.max_content => |vp| {
_ = (if ((vp == css.VendorPrefix{ .none = true })) blk: {
                break :blk self.flushPrefixHelper(property, SizeType, .max_content, dest, context);

} else null);
},
.fit_content => |vp| {
_ = (if ((vp == css.VendorPrefix{ .none = true })) blk: {
                break :blk self.flushPrefixHelper(property, SizeType, .fit_content, dest, context);

} else null);
},
else => {

},
}
                _ = bun.handleOom(dest.append(context.allocator, @unionInit(Property, @tagName(property), val.deepClone(context.allocator))));
                @field(self.flushed_properties, @tagName(property)) = true;
            }
    }

pub inline fn flushLogicalHelper(self: *SizeHandler, comptime property: PropertyIdTag, comptime field: []const u8, comptime physical: PropertyIdTag, comptime SizeType: type, logical_supported: bool, dest: *css.DeclarationList, context: *css.PropertyHandlerContext) void {
            if (logical_supported) {
                _ = self.flushPropertyHelper(property, field, SizeType, dest, context);
            } else {
                _ = self.flushPropertyHelper(physical, field, SizeType, dest, context);
            }
    }
    const Feature = css.Feature;
};

const Printer = css.Printer;
const PrintErr = css.PrintErr;
const PropertyId = css.PropertyId;
const PropertyIdTag = css.PropertyIdTag;
const Property = css.Property;
const UnparsedProperty = css.css_properties.custom.UnparsedProperty;
const PropertyCategory = css.logical.PropertyCategory;
const LengthPercentage = css.css_values.length.LengthPercentage;
const Ratio = css.css_values.ratio.Ratio;
pub const Size = union(enum) {
    /// The `auto` keyworda
    auto,
    /// An explicit length or percentage.
    length_percentage: LengthPercentage,
    /// The `min-content` keyword.
    min_content: css.VendorPrefix,
    /// The `max-content` keyword.
    max_content: css.VendorPrefix,
    /// The `fit-content` keyword.
    fit_content: css.VendorPrefix,
    /// The `fit-content()` function.
    fit_content_function: LengthPercentage,
    /// The `stretch` keyword, or the `-webkit-fill-available` or `-moz-available` prefixed keywords.
    stretch: css.VendorPrefix,
    /// The `contain` keyword.
    contain,

    pub const parse = parseSize;

    pub const toCss = toCssSize;

    pub const isCompatible = isCompatibleSize;

    pub fn deepClone(this: *const @This(), allocator: std.mem.Allocator) @This() {
        return css.implementDeepClone(@This(), this, allocator);
    }

    pub fn eql(lhs: *const @This(), rhs: *const @This()) bool {
        return css.implementEql(@This(), lhs, rhs);
    }
};
pub const MaxSize = union(enum) {
    /// The `none` keyword.
    none,
    /// An explicit length or percentage.
    length_percentage: LengthPercentage,
    /// The `min-content` keyword.
    min_content: css.VendorPrefix,
    /// The `max-content` keyword.
    max_content: css.VendorPrefix,
    /// The `fit-content` keyword.
    fit_content: css.VendorPrefix,
    /// The `fit-content()` function.
    fit_content_function: LengthPercentage,
    /// The `stretch` keyword, or the `-webkit-fill-available` or `-moz-available` prefixed keywords.
    stretch: css.VendorPrefix,
    /// The `contain` keyword.
    contain,

    pub const parse = parseMaxSize;
    pub const toCss = toCssMaxSize;

    pub fn isCompatible(this_ms: *const MaxSize, browsers: css.targets.Browsers) bool {
        const F = css.compat.Feature;
        return switch (this_ms.*) {
            .length_percentage => |*l| l.isCompatible(browsers),
            .min_content => F.isCompatible(.min_content_size, browsers),
            .max_content => F.isCompatible(.max_content_size, browsers),
            .fit_content => F.isCompatible(.fit_content_size, browsers),
            .fit_content_function => |*l| F.isCompatible(F.fit_content_function_size, browsers) and l.isCompatible(browsers),
            .stretch => |*vp| blk: {
                const bits = vp.asBits();
                if (bits == css.VendorPrefix.NONE.asBits()) break :blk F.isCompatible(F.stretch_size, browsers);
                if (bits == css.VendorPrefix.WEBKIT.asBits()) break :blk F.isCompatible(F.webkit_fill_available_size, browsers);
                if (bits == css.VendorPrefix.MOZ.asBits()) break :blk F.isCompatible(F.moz_available_size, browsers);
                break :blk false;
            },
            .contain => false, // ??? no data in mdn
            .none => true,
        };
    }

    pub fn deepClone(this: *const @This(), allocator: std.mem.Allocator) @This() {
        return css.implementDeepClone(@This(), this, allocator);
    }

    pub fn eql(lhs: *const @This(), rhs: *const @This()) bool {
        return css.implementEql(@This(), lhs, rhs);
    }
};
const Allocator = std.mem.Allocator;

pub fn parseSizeKeywordFn(i: *css.Parser) css.Result(Size) {
        const Enum = enum {
        auto,
        @"min-content",
        @"-webkit-min-content",
        @"-moz-min-content",
        @"max-content",
        @"-webkit-max-content",
        @"-moz-max-content",
        stretch,
        @"-webkit-fill-available",
        @"-moz-available",
        @"fit-content",
        @"-webkit-fit-content",
        @"-moz-fit-content",
        contain,
    };
        const Map = (comptime bun.ComptimeEnumMap(Enum));
        const ident_res = i.expectIdent();
        if ((ident_res == .err)) {
            return .{ .err = ident_res.err };
        }
        const ident = ident_res.result;
        if (Map.getASCIIICaseInsensitive(ident)) |res| {
            _ = &res;
            return .{ .result = (switch (res) {
.auto => Size.auto,
.@"min-content" => Size{ .min_content = css.VendorPrefix{ .none = true } },
.@"-webkit-min-content" => Size{ .min_content = css.VendorPrefix{ .webkit = true } },
.@"-moz-min-content" => Size{ .min_content = css.VendorPrefix{ .moz = true } },
.@"max-content" => Size{ .max_content = css.VendorPrefix{ .none = true } },
.@"-webkit-max-content" => Size{ .max_content = css.VendorPrefix{ .webkit = true } },
.@"-moz-max-content" => Size{ .max_content = css.VendorPrefix{ .moz = true } },
.stretch => Size{ .stretch = css.VendorPrefix{ .none = true } },
.@"-webkit-fill-available" => Size{ .stretch = css.VendorPrefix{ .webkit = true } },
.@"-moz-available" => Size{ .stretch = css.VendorPrefix{ .moz = true } },
.@"fit-content" => Size{ .fit_content = css.VendorPrefix{ .none = true } },
.@"-webkit-fit-content" => Size{ .fit_content = css.VendorPrefix{ .webkit = true } },
.@"-moz-fit-content" => Size{ .fit_content = css.VendorPrefix{ .moz = true } },
.contain => Size.contain,
}) };
        } else {
            return .{ .err = i.newCustomError(css.ParserError.invalid_value) };
        }
}

pub fn parseSize(input: *css.Parser) css.Result(Size) {
        const res = input.tryParse(parseSizeKeywordFn, .{});
        if ((res == .result)) {
            return res;
        }
        if (input.tryParse(Size.parseFitContent, .{}).asValue()) |v| {
            _ = &v;
            return .{ .result = Size{ .fit_content_function = v } };
        }
        const lp_res = input.tryParse(LengthPercentage.parse, .{});
        if ((lp_res == .err)) {
            return .{ .err = lp_res.err };
        }
        return .{ .result = Size{ .length_percentage = lp_res.result } };
}

pub fn toCssSize(this_size: *const Size, dest: *css.Printer) css.PrintErr!void {
        return (switch (this_size.*) {
.auto => dest.writeStr("auto"),
.contain => dest.writeStr("contain"),
.min_content => |vp| {
{
            _ = try vp.toCss(dest);
            _ = try dest.writeStr("min-content");
        }
},
.max_content => |vp| {
{
            _ = try vp.toCss(dest);
            _ = try dest.writeStr("max-content");
        }
},
.fit_content => |vp| {
{
            _ = try vp.toCss(dest);
            _ = try dest.writeStr("fit-content");
        }
},
.stretch => |vp| {
if ((vp == css.VendorPrefix{ .none = true })) {
            _ = try dest.writeStr("stretch");
        } else {
            if ((vp == css.VendorPrefix{ .webkit = true })) {
                _ = try dest.writeStr("-webkit-fill-available");
            } else {
                if ((vp == css.VendorPrefix{ .moz = true })) {
                    _ = try dest.writeStr("-moz-available");
                } else {
                    _ = bun.unreachablePanic("Unexpected vendor prefixes", .{});
                }
            }
        }
},
.fit_content_function => |l| {
{
            _ = try dest.writeStr("fit-content(");
            _ = try l.toCss(dest);
            _ = try dest.writeChar(41);
        }
},
.length_percentage => |l| {
return l.toCss(dest);
},
});
}

pub fn isCompatibleSize(this_size: *const Size, browsers: css.targets.Browsers) bool {
        const F = css.compat.Feature;
        return (switch (this_size.*) {
.length_percentage => |*l| l.isCompatible(browsers),
.min_content => F.isCompatible(.min_content_size, browsers),
.max_content => F.isCompatible(.max_content_size, browsers),
.fit_content => F.isCompatible(.fit_content_size, browsers),
.fit_content_function => |*l| (F.isCompatible(.fit_content_function_size, browsers) and l.isCompatible(browsers)),
.stretch => |*vp| {
{
            const bits = vp.asBits();
            if ((bits == css.VendorPrefix.NONE.asBits())) {
                return F.isCompatible(F.stretch_size, browsers);
            }
            if ((bits == css.VendorPrefix.WEBKIT.asBits())) {
                return F.isCompatible(F.webkit_fill_available_size, browsers);
            }
            if ((bits == css.VendorPrefix.MOZ.asBits())) {
                return F.isCompatible(F.moz_available_size, browsers);
            }
            return false;
        }
},
.contain => false,
.auto => true,
});
}

pub fn parseMaxSizeKeywordFn(i: *css.Parser) css.Result(MaxSize) {
        const Ident = enum {
        none,
        min_content,
        webkit_min_content,
        moz_min_content,
        max_content,
        webkit_max_content,
        moz_max_content,
        stretch,
        webkit_fill_available,
        moz_available,
        fit_content,
        webkit_fit_content,
        moz_fit_content,
        contain,
    };
        const IdentMap = bun.ComptimeStringMap(Ident, .{ .{ "none", .none }, .{ "min-content", .min_content }, .{ "-webkit-min-content", .webkit_min_content }, .{ "-moz-min-content", .moz_min_content }, .{ "max-content", .max_content }, .{ "-webkit-max-content", .webkit_max_content }, .{ "-moz-max-content", .moz_max_content }, .{ "stretch", .stretch }, .{ "-webkit-fill-available", .webkit_fill_available }, .{ "-moz-available", .moz_available }, .{ "fit-content", .fit_content }, .{ "-webkit-fit-content", .webkit_fit_content }, .{ "-moz-fit-content", .moz_fit_content }, .{ "contain", .contain } });
        const ident_res = i.expectIdent();
        if ((ident_res == .err)) {
            return .{ .err = ident_res.err };
        }
        const ident = ident_res.result;
        const mapped = IdentMap.getASCIIICaseInsensitive(ident);
        if ((mapped == null)) {
            return .{ .err = i.newCustomError(css.ParserError.invalid_value) };
        }
        return .{ .result = (switch (mapped.?) {
.none => MaxSize.none,
.min_content => MaxSize{ .min_content = .{ .none = true } },
.webkit_min_content => MaxSize{ .min_content = .{ .webkit = true } },
.moz_min_content => MaxSize{ .min_content = .{ .moz = true } },
.max_content => MaxSize{ .max_content = .{ .none = true } },
.webkit_max_content => MaxSize{ .max_content = .{ .webkit = true } },
.moz_max_content => MaxSize{ .max_content = .{ .moz = true } },
.stretch => MaxSize{ .stretch = .{ .none = true } },
.webkit_fill_available => MaxSize{ .stretch = .{ .webkit = true } },
.moz_available => MaxSize{ .stretch = .{ .moz = true } },
.fit_content => MaxSize{ .fit_content = .{ .none = true } },
.webkit_fit_content => MaxSize{ .fit_content = .{ .webkit = true } },
.moz_fit_content => MaxSize{ .fit_content = .{ .moz = true } },
.contain => MaxSize.contain,
}) };
}

pub fn parseMaxSize(input: *css.Parser) css.Result(MaxSize) {
        const res = input.tryParse(parseMaxSizeKeywordFn, .{});
        if (res.isOk()) {
            return res;
        }
        if (input.tryParse(MaxSize.parseFitContent, .{}).asValue()) |v| {
            _ = &v;
            return .{ .result = MaxSize{ .fit_content_function = v } };
        }
        const lp_res = input.tryParse(LengthPercentage.parse, .{});
        if ((lp_res == .err)) {
            return .{ .err = lp_res.err };
        }
        return .{ .result = MaxSize{ .length_percentage = lp_res.result } };
}

pub fn toCssMaxSize(this_ms: *const MaxSize, dest: *css.Printer) css.PrintErr!void {
        switch (this_ms.*) {
.none => {
_ = try dest.writeStr("none");
},
.contain => {
_ = try dest.writeStr("contain");
},
.min_content => |vp| {
_ = try vp.toCss(dest);
        _ = try dest.writeStr("min-content");
},
.max_content => |vp| {
_ = try vp.toCss(dest);
        _ = try dest.writeStr("max-content");
},
.fit_content => |vp| {
_ = try vp.toCss(dest);
        _ = try dest.writeStr("fit-content");
},
.stretch => |vp| {
if ((vp == css.VendorPrefix{ .none = true })) {
            _ = try dest.writeStr("stretch");
        } else {
            if ((vp == css.VendorPrefix{ .webkit = true })) {
                _ = try dest.writeStr("-webkit-fill-available");
            } else {
                if ((vp == css.VendorPrefix{ .moz = true })) {
                    _ = try dest.writeStr("-moz-available");
                } else {
                    _ = bun.unreachablePanic("Unexpected vendor prefixes", .{});
                }
            }
        }
},
.fit_content_function => |l| {
_ = try dest.writeStr("fit-content(");
        _ = try l.toCss(dest);
        _ = try dest.writeChar(41);
},
.length_percentage => |l| {
_ = try l.toCss(dest);
},
}
}

pub fn parseFitContent(input: *css.Parser) css.Result(LengthPercentage) {
        if (input.expectFunctionMatching("fit-content").asErr()) |e| {
            _ = &e;
            return .{ .err = e };
        }
        return input.parseNestedBlock(LengthPercentage, .{}, css.voidWrap(LengthPercentage, LengthPercentage.parse));
}
